__d(function(e,t,i,a,o,s,n){o.exports={version:"2.0",board:"Karnataka State Board / NCERT",grade:7,subject:"Mathematics",textbook:"Mathematics \u2013 Class 7",chapter_number:13,chapter_title:"Exponents and Powers",level_1_mcqs:[{id:"mcq01",difficulty:"Easy",question:"What is 2\u2075?",options:["10","25","32","64"],correct_answer:"32",explanation:"2\u2075 = 2 \xd7 2 \xd7 2 \xd7 2 \xd7 2 = 32. The exponent 5 tells us to multiply 2 by itself 5 times."},{id:"mcq02",difficulty:"Easy",question:"In the expression 7\xb3, what is the base?",options:["3","7","21","343"],correct_answer:"7",explanation:"In 7\xb3, the base is 7 (the number being multiplied repeatedly) and the exponent is 3. 7\xb3 = 7 \xd7 7 \xd7 7 = 343."},{id:"mcq03",difficulty:"Easy",question:"What is the value of 5\u2070?",options:["0","1","5","25"],correct_answer:"1",explanation:"Any non-zero number raised to the power 0 equals 1. 5\u2070 = 1. This is a law of exponents: a\u2070 = 1 for all a \u2260 0."},{id:"mcq04",difficulty:"Easy",question:"Simplify: 3\u2074 \xd7 3\xb2",options:["3\u2076","3\u2078","9\u2076","6\xb3"],correct_answer:"3\u2076",explanation:"Product rule: a\u1d50 \xd7 a\u207f = a\u1d50\u207a\u207f. Since both have base 3, add exponents: 3\u2074 \xd7 3\xb2 = 3\u2074\u207a\xb2 = 3\u2076 = 729. Other options incorrectly multiply or combine bases."},{id:"mcq05",difficulty:"Easy",question:"Simplify: 5\u2077 \xf7 5\xb3",options:["5\u2074","5\xb9\u2070","1\u2074","25\u2074"],correct_answer:"5\u2074",explanation:"Quotient rule: a\u1d50 \xf7 a\u207f = a\u1d50\u207b\u207f. Same base 5, subtract exponents: 5\u2077 \xf7 5\xb3 = 5\u2077\u207b\xb3 = 5\u2074 = 625."},{id:"mcq06",difficulty:"Easy",question:"Simplify: (2\xb3)\u2074",options:["2\u2077","2\xb9\xb2","8\u2074","6\xb2"],correct_answer:"2\xb9\xb2",explanation:"Power of a power rule: (a\u1d50)\u207f = a\u1d50\u02e3\u207f. Multiply the exponents: (2\xb3)\u2074 = 2\xb3\u02e3\u2074 = 2\xb9\xb2 = 4096. Common mistake: adding to get 2\u2077 (wrong \u2014 multiply exponents, don't add)."},{id:"mcq07",difficulty:"Easy",question:"What is (\u22124)\xb2?",options:["\u221216","16","\u22128","8"],correct_answer:"16",explanation:"(\u22124)\xb2 = (\u22124) \xd7 (\u22124) = 16. A negative number raised to an EVEN power always gives a POSITIVE result, because the two negatives cancel each other."},{id:"mcq08",difficulty:"Easy",question:"What is (\u22122)\xb3?",options:["8","6","\u22128","\u22126"],correct_answer:"\u22128",explanation:"(\u22122)\xb3 = (\u22122) \xd7 (\u22122) \xd7 (\u22122) = 4 \xd7 (\u22122) = \u22128. A negative number raised to an ODD power gives a NEGATIVE result."},{id:"mcq09",difficulty:"Easy",question:"Which of the following equals 10\u2074?",options:["400","1,000","10,000","40"],correct_answer:"10,000",explanation:"10\u2074 = 10 \xd7 10 \xd7 10 \xd7 10 = 10,000. The rule: 10\u207f = 1 followed by n zeros. 10\u2074 has 4 zeros: 10,000."},{id:"mcq10",difficulty:"Easy",question:"Express 3,20,000 in standard form.",options:["32 \xd7 10\u2074","3.2 \xd7 10\u2075","3.2 \xd7 10\u2074","32 \xd7 10\xb3"],correct_answer:"3.2 \xd7 10\u2075",explanation:"Standard form: a \xd7 10\u207f where 1 \u2264 a < 10. 3,20,000 \u2192 decimal after first digit: 3.20000; moved 5 places left \u2192 3.2 \xd7 10\u2075. Option 32 \xd7 10\u2074 is wrong because 32 > 10 (not in standard form)."},{id:"mcq11",difficulty:"Easy",question:"Which expression is equivalent to (3 \xd7 5)\xb2?",options:["3 \xd7 5\xb2","3\xb2 \xd7 5","3\xb2 \xd7 5\xb2","3\xb2 + 5\xb2"],correct_answer:"3\xb2 \xd7 5\xb2",explanation:"(ab)\u1d50 = a\u1d50 \xd7 b\u1d50. The exponent distributes over multiplication: (3 \xd7 5)\xb2 = 3\xb2 \xd7 5\xb2 = 9 \xd7 25 = 225. Verify: (15)\xb2 = 225 \u2713."},{id:"mcq12",difficulty:"Easy",question:"What is the prime factorisation of 72 in index form?",options:["2\xb2 \xd7 3\xb3","2\xb3 \xd7 3\xb2","2 \xd7 3 \xd7 12","6\xb2 \xd7 2"],correct_answer:"2\xb3 \xd7 3\xb2",explanation:"72 = 8 \xd7 9 = 2\xb3 \xd7 3\xb2. Verify: 2\xb3 = 8, 3\xb2 = 9, 8 \xd7 9 = 72 \u2713. Index form shows each prime factor and how many times it appears."},{id:"mcq13",difficulty:"Easy",question:"Simplify: 2\xb3 \xd7 2\u2074 \xf7 2\u2075",options:["2\xb2","2\xb9\xb2","2\u2076","2\u2070"],correct_answer:"2\xb2",explanation:"All base 2. Product rule: 2\xb3 \xd7 2\u2074 = 2\u2077. Quotient rule: 2\u2077 \xf7 2\u2075 = 2\xb2. Or directly: 2^(3+4\u22125) = 2\xb2 = 4."},{id:"mcq14",difficulty:"Easy",question:"Which of the following is TRUE?",options:["2\xb3 + 2\xb3 = 2\u2076","2\xb3 \xd7 2\xb3 = 2\u2076","2\xb3 \xd7 2\xb3 = 4\u2076","2\xb3 + 2\xb3 = 4\xb3"],correct_answer:"2\xb3 \xd7 2\xb3 = 2\u2076",explanation:"2\xb3 \xd7 2\xb3 = 2\xb3\u207a\xb3 = 2\u2076 \u2713 (product rule). 2\xb3 + 2\xb3 = 8 + 8 = 16 = 2\u2074 \u2260 2\u2076. Laws of exponents apply to multiplication, NOT addition."},{id:"mcq15",difficulty:"Easy",question:"What is 1\u2075\u2070\u2070?",options:["500","1","1500","0"],correct_answer:"1",explanation:"1 raised to any power equals 1. 1\u2075\u2070\u2070 = 1 \xd7 1 \xd7 1 \xd7 ... (500 times) = 1. No matter how many times you multiply 1 by itself, it stays 1."},{id:"mcq16",difficulty:"Easy",question:"If 3\u02e3 = 243, what is x?",options:["4","5","6","3"],correct_answer:"5",explanation:"Express 243 as power of 3: 3\xb9=3, 3\xb2=9, 3\xb3=27, 3\u2074=81, 3\u2075=243. So 3\u02e3 = 3\u2075, therefore x = 5."},{id:"mcq17",difficulty:"Easy",question:"The speed of light is approximately 3 \xd7 10\u2075 km/s. How far does it travel in 10 seconds?",options:["3 \xd7 10\u2074 km","3 \xd7 10\u2076 km","30 \xd7 10\u2075 km","3 \xd7 10\u2075 km"],correct_answer:"3 \xd7 10\u2076 km",explanation:"Distance = speed \xd7 time = 3 \xd7 10\u2075 \xd7 10 = 3 \xd7 10\u2075 \xd7 10\xb9 = 3 \xd7 10\u2075\u207a\xb9 = 3 \xd7 10\u2076 km. Product rule: 10\u2075 \xd7 10\xb9 = 10\u2076."},{id:"mcq18",difficulty:"Easy",question:"Which of these is NOT a correct law of exponents?",options:["a\u1d50 \xd7 a\u207f = a\u1d50\u207a\u207f","(a\u1d50)\u207f = a\u1d50\u207f","a\u1d50 + a\u207f = a\u1d50\u207a\u207f","a\u1d50 \xf7 a\u207f = a\u1d50\u207b\u207f"],correct_answer:"a\u1d50 + a\u207f = a\u1d50\u207a\u207f",explanation:"Laws of exponents apply to MULTIPLICATION and DIVISION, NOT addition. a\u1d50 + a\u207f \u2260 a\u1d50\u207a\u207f. For example, 2\xb2 + 2\xb3 = 4 + 8 = 12, but 2\xb2\u207a\xb3 = 2\u2075 = 32. Very different!"},{id:"mcq19",difficulty:"Easy",question:"What is 10\u2070 + 2\xb9 + 3\u2070?",options:["6","4","3","0"],correct_answer:"4",explanation:"10\u2070 = 1 (any non-zero to power 0 = 1). 2\xb9 = 2 (any number to power 1 = itself). 3\u2070 = 1. Sum = 1 + 2 + 1 = 4."},{id:"mcq20",difficulty:"Easy",question:"1 GB of computer storage = 2\xb3\u2070 bytes. Using the product rule, how many bytes is 4 GB?",options:["2\xb3\xb2 bytes","8\xb3\u2070 bytes","2\xb9\xb2\u2070 bytes","4 \xd7 2\xb3\u2070 bytes (= 2\xb2 \xd7 2\xb3\u2070 = 2\xb3\xb2)"],correct_answer:"4 \xd7 2\xb3\u2070 bytes (= 2\xb2 \xd7 2\xb3\u2070 = 2\xb3\xb2)",explanation:"4 GB = 4 \xd7 2\xb3\u2070 bytes = 2\xb2 \xd7 2\xb3\u2070 = 2\xb2\u207a\xb3\u2070 = 2\xb3\xb2 bytes (product rule). 4 = 2\xb2, so the calculation uses the same base (2) and adds exponents. This is exactly how computer scientists calculate storage."}],common_misconceptions:[{misconception:"2\xb3 means 2 \xd7 3 = 6",why_confused:"Students see two numbers (2 and 3) and instinctively multiply them as a default operation.",correct_explanation:"2\xb3 means 2 \xd7 2 \xd7 2 = 8. The exponent 3 tells you how many times to use 2 as a FACTOR (multiply it by itself), not how many times to add it or multiply it directly by 3. 2\xb3 \u2260 2\xd73=6. Always expand: 2\xb3 = 2\xd72\xd72 = 8.",mini_practice_question:"Which is correct: 3\u2074 = 12 or 3\u2074 = 81?",answer:"3\u2074 = 81. Because 3\u2074 = 3 \xd7 3 \xd7 3 \xd7 3 = 9 \xd7 9 = 81. NOT 3 \xd7 4 = 12."},{misconception:"The product rule applies to any two powers: 2\xb3 \xd7 3\u2074 = 6\u2077",why_confused:"Students see the rule 'add exponents' and apply it regardless of base, sometimes also adding the bases.",correct_explanation:"The product rule a\u1d50 \xd7 a\u207f = a\u1d50\u207a\u207f ONLY works when BOTH powers have EXACTLY THE SAME BASE. 2\xb3 \xd7 3\u2074 cannot be simplified with this rule \u2014 the bases 2 and 3 are different. You must evaluate separately: 8 \xd7 81 = 648. Also, you cannot add the bases (2+3=5 or 2\xd73=6 with 3+4=7 is completely wrong).",mini_practice_question:"Can you simplify 5\xb2 \xd7 5\xb3 using the product rule? Can you simplify 2\u2074 \xd7 3\xb2 using the product rule?",answer:"5\xb2 \xd7 5\xb3 = 5\u2075 \u2713 (same base \u2014 product rule applies). 2\u2074 \xd7 3\xb2 CANNOT be simplified using the product rule (different bases). Must calculate: 16 \xd7 9 = 144."}]}},2781,[]);